import json
import subprocess
from pathlib import Path

wt = Path("/Users/steventran/.do_again/selfdev-20261007")
if not wt.is_dir():
    raise SystemExit(f"missing isolated worktree: {wt}")

def run(*args):
    return subprocess.check_output(args, cwd=wt, text=True).strip()

status = {
    "worktree": str(wt),
    "branch": run("git", "branch", "--show-current"),
    "head": run("git", "rev-parse", "HEAD"),
    "status_porcelain": run("git", "status", "--porcelain=v1"),
    "origin_main": run("git", "rev-parse", "origin/main"),
    "remote": run("git", "remote", "-v"),
}

policy_candidates = [
    wt / "do-again-policy.json",
    wt / "do-again.toml",
    wt / "pyproject.toml",
]
status["files"] = {
    str(p.name): {
        "exists": p.exists(),
        "size": p.stat().st_size if p.exists() else None,
    }
    for p in policy_candidates
}

print(json.dumps(status, indent=2))
